from abc import ABC, abstractmethod
from decimal import Decimal


class KaspiBankProtocol:
    """Сторонний протокол платежей Kaspi Bank."""

    def execute_payment(self, account: str, amount_kzt: int) -> dict:
        """Выполнить платёж через шлюз банка."""
        if amount_kzt <= 0:
            return {"status": "FAIL", "error": "Сумма должна быть положительной"}
        return {"status": "OK", "tx_id": f"KASPI-TX-{amount_kzt}"}


class PaymentProcessor(ABC):
    """Абстрактный доменный процессор платежей Avtobys."""

    @abstractmethod
    def process_payment(self, user_id: str, amount: Decimal) -> bool:
        """Списать средства со счёта пользователя."""
        ...


class KaspiBankAdapter(PaymentProcessor):
    """Адаптер протокола KaspiBank к доменному интерфейсу PaymentProcessor."""

    def __init__(self, kaspi_api: KaspiBankProtocol) -> None:
        self._api = kaspi_api

    def process_payment(self, user_id: str, amount: Decimal) -> bool:
        if amount <= Decimal("0"):
            return False
        amount_kzt = int(amount)
        result = self._api.execute_payment(account=user_id, amount_kzt=amount_kzt)
        return result.get("status") == "OK"


class TransactionDecorator(PaymentProcessor):
    """Базовый абстрактный декоратор платежного процессора."""

    def __init__(self, wrapped: PaymentProcessor) -> None:
        self._wrapped = wrapped

    def process_payment(self, user_id: str, amount: Decimal) -> bool:
        return self._wrapped.process_payment(user_id, amount)


class AuditLoggingDecorator(TransactionDecorator):
    """Декоратор, выполняющий прозрачный аудит всех транзакций."""

    def __init__(self, wrapped: PaymentProcessor) -> None:
        super().__init__(wrapped)
        self.log: list[str] = []

    def process_payment(self, user_id: str, amount: Decimal) -> bool:
        success = self._wrapped.process_payment(user_id, amount)
        self.log.append(f"AUDIT: user={user_id}, amount={amount}, success={success}")
        return success


class ValidationHandler(ABC):
    """Базовый класс звена цепочки валидации транзакций."""

    def __init__(self) -> None:
        self._next_handler: ValidationHandler | None = None

    def set_next(self, handler: "ValidationHandler") -> "ValidationHandler":
        self._next_handler = handler
        return handler

    def validate(self, tx: dict) -> bool:
        if self._next_handler:
            return self._next_handler.validate(tx)
        return True


class StopListHandler(ValidationHandler):
    """Обработчик проверки пользователя по чёрному списку (стоп-листу)."""

    def __init__(self, blocked_users: set[str] | list[str]) -> None:
        super().__init__()
        self._blocked = set(blocked_users)

    def validate(self, tx: dict) -> bool:
        if tx.get("user_id") in self._blocked:
            return False
        return super().validate(tx)


class LimitCheckHandler(ValidationHandler):
    """Обработчик проверки разового лимита суммы транзакции."""

    def __init__(self, max_limit: Decimal = Decimal("5000")) -> None:
        super().__init__()
        self._limit = max_limit

    def validate(self, tx: dict) -> bool:
        if tx.get("amount", Decimal("0")) > self._limit:
            return False
        return super().validate(tx)


def build_payment_system(
    bank_protocol: KaspiBankProtocol | None = None,
    blocked_users: set[str] | None = None,
    max_limit: Decimal | None = None,
) -> tuple[ValidationHandler, AuditLoggingDecorator]:
    """Собрать цепочку валидации и декорированный процессор платежей."""
    if bank_protocol is None:
        bank_protocol = KaspiBankProtocol()
    if blocked_users is None:
        blocked_users = set()
    if max_limit is None:
        max_limit = Decimal("5000")

    stop_handler = StopListHandler(blocked_users)
    limit_handler = LimitCheckHandler(max_limit)
    stop_handler.set_next(limit_handler)

    adapter = KaspiBankAdapter(bank_protocol)
    auditor = AuditLoggingDecorator(adapter)
    return stop_handler, auditor
